package com.enjoycare.dao;
import com.enjoycare.HibernateUtil; import com.enjoycare.entity.Teknisi; import java.util.List; import org.hibernate.Session; import org.hibernate.Transaction;
public class TeknisiDAO { public List<Teknisi> getAll(){try(Session s=HibernateUtil.getSessionFactory().openSession()){return s.createQuery("FROM Teknisi t ORDER BY t.idTeknisi DESC",Teknisi.class).list();}} public List<Teknisi> getAktif(){try(Session s=HibernateUtil.getSessionFactory().openSession()){return s.createQuery("FROM Teknisi t WHERE t.aktif=true ORDER BY t.namaTeknisi",Teknisi.class).list();}} public Teknisi getById(Long id){try(Session s=HibernateUtil.getSessionFactory().openSession()){return s.get(Teknisi.class,id);}} public void save(Teknisi x){Transaction tx=null;try(Session s=HibernateUtil.getSessionFactory().openSession()){tx=s.beginTransaction();if(x.getIdTeknisi()==null)s.save(x);else s.merge(x);tx.commit();}catch(RuntimeException e){if(tx!=null&&tx.isActive())tx.rollback();throw e;}} public void delete(Long id){Transaction tx=null;try(Session s=HibernateUtil.getSessionFactory().openSession()){tx=s.beginTransaction();Teknisi x=s.get(Teknisi.class,id);if(x!=null)s.delete(x);tx.commit();}catch(RuntimeException e){if(tx!=null&&tx.isActive())tx.rollback();throw e;}}}
